<template><view class="page"><view class="nav"><text @tap="back" class="cuIcon-back"/><view><text class="kicker">CAMPUS EDITIONS</text><text class="brand">见字</text></view><text @tap="openMine" class="cuIcon-form"/></view><scroll-view scroll-y class="scroll"><view class="hero"><text class="eyebrow">慢一点，读一篇文章</text><text class="hero-title">让校园里的想法，拥有自己的版面。</text><text class="hero-desc">见字收录校园里的故事、观点与灵感。每一篇文章，都值得被认真读完。</text></view><view class="heading"><text>校园刊物</text><text @tap="openSubmit">我要投稿 ·</text></view><scroll-view scroll-x class="shelf"><view v-for="(j,i) in journals" :key="j.id" class="card" @tap="openJournal(j)"><view class="cover" :style="palette(i)"><image v-if="j.coverUrl" :src="j.coverUrl" mode="aspectFill"/><view class="shade"/><text>{{j.name}}</text><small>{{j.description||'文字 · 观点 · 生活'}}</small></view><text class="card-name">《{{j.name}}》</text></view><view v-if="!journals.length" class="empty">编辑部正在准备第一期刊物</view></scroll-view><view class="heading reading"><text>正在发生</text><view><text v-for="x in sorts" :key="x.value" :class="{active:sort===x.value}" @tap="changeSort(x.value)">{{x.label}}</text></view></view><view v-for="a in articles" :key="a.id" class="article" @tap="openArticle(a)"><view><small>{{a.journalName||'见字'}} · {{date(a.publishedAt||a.created)}}</small><text>{{a.title}}</text><p>{{a.summary||excerpt(a.bodyMarkdown)}}</p><small>{{a.authorName||'见字作者'}} · {{a.views||0}} 阅读</small></view><image v-if="a.coverUrl" :src="a.coverUrl" mode="aspectFill"/></view><view v-if="loading" class="empty">正在翻开下一页</view><view v-else-if="!articles.length" class="empty">这里还没有公开文章 · <text @tap="openSubmit">成为第一位投稿者</text></view></scroll-view></view></template>
<script>
export default {data(){return {journals:[],articles:[],sort:'recommend',loading:true,sorts:[{label:'推荐',value:'recommend'},{label:'最新',value:'latest'},{label:'热门',value:'hot'}]}},onLoad(){this.loadJournals();this.loadArticles()},onShow(){this.loadJournals();this.loadArticles()},methods:{back(){uni.navigateBack({delta:1})},loadJournals(){this.$Net.request({url:this.$API.journalList(),data:{page:1,limit:40,_ts:Date.now()},method:'get',dataType:'json',success:r=>{this.journals=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[]}})},loadArticles(){this.loading=true;this.$Net.request({url:this.$API.journalArticleList(),data:{journalId:0,page:1,limit:50,sort:this.sort,_ts:Date.now()},method:'get',dataType:'json',success:r=>{const rows=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[];this.articles=rows.filter(item=>item&&item.status==='published');this.loading=false},fail:()=>{this.articles=[];this.loading=false}})},changeSort(v){if(this.sort!==v){this.sort=v;this.loadArticles()}},openJournal(j){uni.navigateTo({url:'/pages/journal/info?id='+j.id})},openArticle(a){uni.navigateTo({url:'/pages/journal/article?id='+a.id})},openSubmit(){uni.navigateTo({url:'/pages/journal/post'})},openMine(){uni.navigateTo({url:'/pages/journal/submissions'})},palette(i){return {background:['#1c3c38','#c9835d','#345c72','#899b6d','#6c5a79'][i%5]}},excerpt(v){return String(v||'').replace(/[#>*_`\[\]]/g,'').replace(/\s+/g,' ').trim().slice(0,100)},date(v){let d=new Date(Number(v)>10000000000?Number(v):Number(v)*1000);return isNaN(d.getTime())?'':d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0')}}}
</script>
<style scoped>.page{min-height:100vh;background:#f4f1eb;color:#17211f}.nav{position:sticky;top:0;z-index:3;display:flex;justify-content:space-between;align-items:center;padding:calc(22px + env(safe-area-inset-top)) 24px 16px;background:#f4f1ebe8}.nav view{display:flex;align-items:center;gap:10px}.kicker,.eyebrow,small{font-size:10px;letter-spacing:1.8px;color:#87968f}.brand{font:28px Georgia,serif;color:#285448}.scroll{min-height:100vh}.hero{padding:44px 24px 38px;border-bottom:1px solid #d8dfd9}.hero-title{display:block;max-width:680px;margin-top:14px;font:clamp(36px,7vw,66px)/1.05 Georgia,serif;color:#203c35}.hero-desc{display:block;max-width:500px;margin-top:18px;color:#71817a;line-height:1.7}.heading{display:flex;justify-content:space-between;align-items:end;padding:30px 24px 17px;font:29px Georgia,serif;color:#294a40}.heading>text:last-child,.heading view{font:13px sans-serif;color:#648077}.shelf{padding:0 24px 30px;white-space:nowrap}.card{display:inline-block;width:188px;margin-right:14px;vertical-align:top}.cover{position:relative;height:270px;overflow:hidden;border-radius:9px;box-shadow:0 18px 34px #2339322e;color:#fff}.cover image{width:100%;height:100%;opacity:.74}.shade{position:absolute;inset:0;background:linear-gradient(#0a1e1a08,#0a1916d1)}.cover>text,.cover small{position:absolute;left:16px;right:12px;bottom:35px;font:25px Georgia,serif;color:#fff}.cover small{bottom:14px;font:11px sans-serif;opacity:.82}.card-name{display:block;margin-top:10px;color:#294a40}.empty{text-align:center;padding:70px 24px;color:#8b9a93}.empty text{color:#567f70}.reading{border-top:1px solid #d8dfd9}.heading view text{margin-left:16px}.heading view .active{color:#a0643f;border-bottom:2px solid #a0643f;padding-bottom:6px}.article{display:flex;gap:18px;padding:23px 24px;border-bottom:1px solid #d8dfd9}.article>view{flex:1;min-width:0}.article>view>text{display:block;margin:10px 0 8px;font:26px Georgia,serif;color:#203c35}.article p{margin:0;color:#6f8078;line-height:1.65}.article image{width:108px;height:122px;border-radius:6px}@media(max-width:480px){.hero-title{font-size:38px}.card{width:164px}.cover{height:236px}.article image{width:88px;height:106px}.article>view>text{font-size:23px}}
</style>
